selector_to_html = {"a[href=\"#pyskyfire.pump.impeller.outlet_width_ratio\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.pump.impeller.outlet_width_ratio\">\n<span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.pump.impeller.</span></span><span class=\"sig-name descname\"><span class=\"pre\">outlet_width_ratio</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">nq</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Mean relative outlet width b2/d2 of radial impellers, G\u00fclich Eq. (7.1).</p></dd>", "a[href=\"Impeller.html#pyskyfire.pump.impeller.Impeller\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.pump.impeller.Impeller\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.pump.impeller.</span></span><span class=\"sig-name descname\"><span class=\"pre\">Impeller</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">Q</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">H</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">n</span></span></em>, <em class=\"sig-param\"><span class=\"keyword-only-separator o\"><abbr title=\"Keyword-only parameters separator (PEP 3102)\"><span class=\"pre\">*</span></abbr></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">shaft_diameter</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">inlet_hub_diameter</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">blade_count</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">blade_thickness</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">hydraulic_efficiency</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">beta2_deg</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">psi</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">d2</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">u2</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">fT</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">1.0</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">b2</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">phi1</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">0.2</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">d1</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">beta1_deg</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">incidence_deg</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">0.0</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">inlet_prewhirl</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">0.0</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">wrap_deg</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">volumetric_efficiency</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">1.0</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">rho</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">tip_clearance</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">0.0</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">meridional</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">axial_length</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">blade_settings</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">splitter</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">rotation</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">COUNTERCLOCKWISE</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Size a radial impeller; call build_geometry() to generate pyTurbo surfaces.</p><p>Required lengths are in metres. <code class=\"docutils literal notranslate\"><span class=\"pre\">blade_thickness</span></code> is total section-normal\nbody thickness: a float or function of chord_fraction, span_fraction, x, r.\nAngle and prewhirl functions accept span_fraction, x, r. Span runs hub to\nblade tip, including when tip clearance is present. <code class=\"docutils literal notranslate\"><span class=\"pre\">phi1</span></code> refers to the\nunblocked inlet annulus, and d1 overrides its sizing equation.</p><p><code class=\"docutils literal notranslate\"><span class=\"pre\">H</span></code> is the total head at the impeller outlet and <code class=\"docutils literal notranslate\"><span class=\"pre\">hydraulic_efficiency</span></code>\nthe impeller\u2019s own (see the module notes); it is a supplied assumption,\nnever predicted here. The design is closed on one quantity. By default\n<code class=\"docutils literal notranslate\"><span class=\"pre\">beta2_deg</span></code> is solved and the outlet diameter comes from one of <code class=\"docutils literal notranslate\"><span class=\"pre\">psi</span></code>,\n<code class=\"docutils literal notranslate\"><span class=\"pre\">d2</span></code>, <code class=\"docutils literal notranslate\"><span class=\"pre\">u2</span></code> or a supplied <code class=\"docutils literal notranslate\"><span class=\"pre\">meridional</span></code>, or failing all of them from\nEq. (3.26) at <code class=\"docutils literal notranslate\"><span class=\"pre\">fT</span></code>. Give <code class=\"docutils literal notranslate\"><span class=\"pre\">beta2_deg</span></code> instead and <code class=\"docutils literal notranslate\"><span class=\"pre\">d2</span></code> is solved. Giving\nboth over-specifies the wheel. The solved angle is the one below the peak\nof the swirl it can deliver: at low specific speed that peak is broad and\nflat, and a head above it cannot be had at any angle, which is reported\nwith the head coefficient that can.</p><p><code class=\"docutils literal notranslate\"><span class=\"pre\">blade_count</span></code> is always an input. G\u00fclich rejects empirical blade-count\nformulas as likely to violate the criteria that actually set it: pressure\npulsations against the collector, blade loading, head-curve stability.\nSplitters do not count toward it in the slip prediction.</p><p><code class=\"docutils literal notranslate\"><span class=\"pre\">incidence_deg</span></code> means metal angle minus unblocked relative inlet flow\nangle. No leakage is assumed for volumetric_efficiency=1. <code class=\"docutils literal notranslate\"><span class=\"pre\">b2</span></code> defaults\nto Eq. (7.1).</p><p><code class=\"docutils literal notranslate\"><span class=\"pre\">rotation</span></code> is which way the wheel turns about its own +x shaft, and only\nmirrors the blades: every velocity triangle is a magnitude in the rotating\nframe and is the same either way. It has to match the sense of the volute\ncollecting the discharge, once both are placed.\nCreate a new Impeller to change design inputs; build_geometry can be repeated\nat different numerical resolutions using the same resolved definition.</p></dd>", "a[href=\"#attributes\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Attributes<a class=\"headerlink\" href=\"#attributes\" title=\"Link to this heading\">\u00b6</a></h2>", "a[href=\"#pyskyfire.pump.impeller.inlet_diameter_from_phi\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.pump.impeller.inlet_diameter_from_phi\">\n<span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.pump.impeller.</span></span><span class=\"sig-name descname\"><span class=\"pre\">inlet_diameter_from_phi</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"keyword-only-separator o\"><abbr title=\"Keyword-only parameters separator (PEP 3102)\"><span class=\"pre\">*</span></abbr></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">Q</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">n</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">phi1</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">inlet_hub_diameter</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Solve annular continuity for a fixed wetted hub and Cm1 = phi1*Ueye.</p></dd>", "a[href=\"OutletSlip.html#pyskyfire.pump.impeller.OutletSlip\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.pump.impeller.OutletSlip\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.pump.impeller.</span></span><span class=\"sig-name descname\"><span class=\"pre\">OutletSlip</span></span></dt><dd><p>G\u00fclich\u2019s slip prediction at the impeller outlet, Table 3.2.</p><p><code class=\"docutils literal notranslate\"><span class=\"pre\">blockage</span></code> is tau_2 (T3.2.3), <code class=\"docutils literal notranslate\"><span class=\"pre\">limiting_ratio</span></code> epsilon_lim (T3.2.4),\n<code class=\"docutils literal notranslate\"><span class=\"pre\">diameter_correction</span></code> k_w (T3.2.5) and <code class=\"docutils literal notranslate\"><span class=\"pre\">slip_factor</span></code> gamma (T3.2.6).\n<code class=\"docutils literal notranslate\"><span class=\"pre\">cm</span></code> is the unblocked meridional velocity and <code class=\"docutils literal notranslate\"><span class=\"pre\">cu</span></code> the absolute swirl\nthe blades leave (T3.2.7), both in m/s.</p></dd>", "a[href=\"#pyskyfire.pump.impeller.design_value\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.pump.impeller.design_value\">\n<span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.pump.impeller.</span></span><span class=\"sig-name descname\"><span class=\"pre\">design_value</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">value</span></span></em>, <em class=\"sig-param\"><span class=\"keyword-only-separator o\"><abbr title=\"Keyword-only parameters separator (PEP 3102)\"><span class=\"pre\">*</span></abbr></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">label</span></span></em>, <em class=\"sig-param\"><span class=\"o\"><span class=\"pre\">**</span></span><span class=\"n\"><span class=\"pre\">context</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Dispatch a scalar callback by its requested keyword names.</p><p>Angle/prewhirl callbacks receive span_fraction, x, r. Thickness callbacks\nadditionally receive chord_fraction (normalized m-prime along the blade).\nCallbacks are evaluated at scalar positions and must return finite scalars.</p></dd>", "a[href=\"VelocityTriangle.html#pyskyfire.pump.impeller.VelocityTriangle\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.pump.impeller.VelocityTriangle\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.pump.impeller.</span></span><span class=\"sig-name descname\"><span class=\"pre\">VelocityTriangle</span></span></dt><dd></dd>", "a[href=\"#pyskyfire.pump.impeller.outlet_diameter\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.pump.impeller.outlet_diameter\">\n<span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.pump.impeller.</span></span><span class=\"sig-name descname\"><span class=\"pre\">outlet_diameter</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">psi</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">n</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">H</span></span></em><span class=\"sig-paren\">)</span></dt><dd></dd>", "a[href=\"#module-pyskyfire.pump.impeller\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pyskyfire.pump.impeller<a class=\"headerlink\" href=\"#module-pyskyfire.pump.impeller\" title=\"Link to this heading\">\u00b6</a></h1><p>Preliminary radial impeller sizing and physical inputs for pyTurbo Aero.</p><p>No surface generator or efficiency predictor is run during construction.\nMetal angles are measured from the backward circumferential direction toward\nthe meridional direction. Positive wrap denotes backward sweep for +x rotation.</p>", "a[href=\"#pyskyfire.pump.impeller._section_path\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.pump.impeller._section_path\">\n<span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.pump.impeller.</span></span><span class=\"sig-name descname\"><span class=\"pre\">_section_path</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">passage</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">settings</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">span</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Normalised m\u2019 fraction and (x, r) samples along one blade section.</p></dd>", "a[href=\"#pyskyfire.pump.impeller.outlet_slip\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.pump.impeller.outlet_slip\">\n<span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.pump.impeller.</span></span><span class=\"sig-name descname\"><span class=\"pre\">outlet_slip</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"keyword-only-separator o\"><abbr title=\"Keyword-only parameters separator (PEP 3102)\"><span class=\"pre\">*</span></abbr></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">beta2_deg</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">blade_count</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">d2</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">b2</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">u2</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">flow</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">blade_thickness</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">d1m</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">f1</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">0.98</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Swirl a radial wheel leaves with, including slip (G\u00fclich Table 3.2).</p><p><code class=\"docutils literal notranslate\"><span class=\"pre\">flow</span></code> is the flow through the impeller, leakage included. <code class=\"docutils literal notranslate\"><span class=\"pre\">d1m</span></code> is the\nmean leading-edge diameter, which lowers the slip factor once it reaches\nfar enough out that the blades are too short to guide the flow.\n<code class=\"docutils literal notranslate\"><span class=\"pre\">blade_thickness</span></code> is the full body thickness: G\u00fclich correlated the\nfactor with it as the blockage, not with a thinned trailing edge. <code class=\"docutils literal notranslate\"><span class=\"pre\">f1</span></code>\nis 0.98 for radial impellers. The correlation reproduces tests with a\nstandard deviation of about 4 percent.</p></dd>", "a[href=\"#functions\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Functions<a class=\"headerlink\" href=\"#functions\" title=\"Link to this heading\">\u00b6</a></h2>", "a[href=\"#pyskyfire.pump.impeller.meridional_contours\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.pump.impeller.meridional_contours\">\n<span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.pump.impeller.</span></span><span class=\"sig-name descname\"><span class=\"pre\">meridional_contours</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">d1</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">dh</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">d2</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">b2</span></span></em>, <em class=\"sig-param\"><span class=\"keyword-only-separator o\"><abbr title=\"Keyword-only parameters separator (PEP 3102)\"><span class=\"pre\">*</span></abbr></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">axial_length</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Smooth quarter-ellipse endwalls with axial inlet and radial outlet.</p><p>The inlet is x=0; the shroud outlet is x=L and hub outlet x=L+b2.\nAxial length is a design choice, with a preliminary dimension-based default.</p></dd>", "a[href=\"#pyskyfire.pump.impeller.G0\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.pump.impeller.G0\">\n<span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.pump.impeller.</span></span><span class=\"sig-name descname\"><span class=\"pre\">G0</span></span><span class=\"property\"><span class=\"w\"> </span><span class=\"p\"><span class=\"pre\">=</span></span><span class=\"w\"> </span><span class=\"pre\">9.80665</span></span></dt><dd></dd>", "a[href=\"ImpellerDiagnostics.html#pyskyfire.pump.impeller.ImpellerDiagnostics\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.pump.impeller.ImpellerDiagnostics\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.pump.impeller.</span></span><span class=\"sig-name descname\"><span class=\"pre\">ImpellerDiagnostics</span></span></dt><dd><p>How the closed design sits against G\u00fclich\u2019s guidance. Nothing is enforced.</p><p><code class=\"docutils literal notranslate\"><span class=\"pre\">solved</span></code> names what the head was closed on, <code class=\"docutils literal notranslate\"><span class=\"pre\">\"beta2\"</span></code> or <code class=\"docutils literal notranslate\"><span class=\"pre\">\"d2\"</span></code>.\n<code class=\"docutils literal notranslate\"><span class=\"pre\">psi</span></code> is the resolved head coefficient 2gH/u2\u00b2 and <code class=\"docutils literal notranslate\"><span class=\"pre\">psi_correlation</span></code>\nwhat Eq. (3.26) proposes at this specific speed and <code class=\"docutils literal notranslate\"><span class=\"pre\">fT</span></code>. <code class=\"docutils literal notranslate\"><span class=\"pre\">slip</span></code> is the\nmean-streamline prediction. <code class=\"docutils literal notranslate\"><span class=\"pre\">deviation_deg</span></code> is beta2B minus the flow\nangle, which G\u00fclich suggests keeping below 10 to 14 degrees, and\n<code class=\"docutils literal notranslate\"><span class=\"pre\">deceleration_ratio</span></code> is w2 over w1 at the shroud, whose de Haller limit\nhe puts at 0.7.</p></dd>", "a[href=\"#pyskyfire.pump.impeller._positive\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.pump.impeller._positive\">\n<span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.pump.impeller.</span></span><span class=\"sig-name descname\"><span class=\"pre\">_positive</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">value</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">name</span></span></em>, <em class=\"sig-param\"><span class=\"keyword-only-separator o\"><abbr title=\"Keyword-only parameters separator (PEP 3102)\"><span class=\"pre\">*</span></abbr></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">zero</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">False</span></span></em><span class=\"sig-paren\">)</span></dt><dd></dd>", "a[href=\"#classes\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Classes<a class=\"headerlink\" href=\"#classes\" title=\"Link to this heading\">\u00b6</a></h2>", "a[href=\"ImpellerDimensions.html#pyskyfire.pump.impeller.ImpellerDimensions\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.pump.impeller.ImpellerDimensions\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.pump.impeller.</span></span><span class=\"sig-name descname\"><span class=\"pre\">ImpellerDimensions</span></span></dt><dd></dd>", "a[href=\"#pyskyfire.pump.impeller.specific_speed\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.pump.impeller.specific_speed\">\n<span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.pump.impeller.</span></span><span class=\"sig-name descname\"><span class=\"pre\">specific_speed</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">n</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">Q</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">H</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>G\u00fclich nq convention: rpm, m\u00b3/s, m.</p></dd>", "a[href=\"#module-contents\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Module Contents<a class=\"headerlink\" href=\"#module-contents\" title=\"Link to this heading\">\u00b6</a></h2>", "a[href=\"ImpellerVelocityTriangles.html#pyskyfire.pump.impeller.ImpellerVelocityTriangles\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.pump.impeller.ImpellerVelocityTriangles\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.pump.impeller.</span></span><span class=\"sig-name descname\"><span class=\"pre\">ImpellerVelocityTriangles</span></span></dt><dd></dd>", "a[href=\"#references\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">References<a class=\"headerlink\" href=\"#references\" title=\"Link to this heading\">\u00b6</a></h2><p>G\u00fclich, J. F., <em>Centrifugal Pumps</em>, 4th ed., Springer, 2020. Table 3.2,\nEq. (3.26), Eq. (7.1) and chapter 7.2.</p>", "a[href=\"#pyskyfire.pump.impeller.pressure_coefficient\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.pump.impeller.pressure_coefficient\">\n<span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.pump.impeller.</span></span><span class=\"sig-name descname\"><span class=\"pre\">pressure_coefficient</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">nq</span></span></em>, <em class=\"sig-param\"><span class=\"keyword-only-separator o\"><abbr title=\"Keyword-only parameters separator (PEP 3102)\"><span class=\"pre\">*</span></abbr></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">fT</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">1.0</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Best-efficiency head coefficient of radial pumps, G\u00fclich Eq. (3.26).</p><p>A mean curve through measured industrial pumps, so it proposes an outlet\ndiameter rather than fixing one. <code class=\"docutils literal notranslate\"><span class=\"pre\">fT</span></code> says where in the scatter band the\ndesign sits: G\u00fclich finds 1.0 describes multistage pumps and 1.1 low-head\nsingle-stage volute pumps (EN 733). A higher coefficient gives a smaller\nwheel and a flatter, less stable head curve.</p></dd>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 600, interactive: false,
                onShow(instance) {MathJax.typesetPromise([instance.popper]).then(() => {});},
            });
        };
    };
    console.log("tippy tips loaded!");
};
